import csv
import io


def parse_csv(raw_csv: str):
    old_limit = csv.field_size_limit()
    try:
        if len(raw_csv) > old_limit:
            csv.field_size_limit(len(raw_csv))
        records = list(csv.reader(
            io.StringIO(raw_csv, newline=""),
            delimiter=";",
            quotechar='"',
            doublequote=True,
            strict=False,
        ))
    finally:
        if csv.field_size_limit() != old_limit:
            csv.field_size_limit(old_limit)

    if not records:
        return {"columns": [], "rows": []}

    columns = records[0]
    if columns:
        columns[0] = columns[0].removeprefix("\ufeff")

    rows = records[1:]
    width = max([len(columns)] + [len(row) for row in rows])
    used_names = set(columns)

    while len(columns) < width:
        number = len(columns) + 1
        name = f"column_{number}"
        suffix = 2
        while name in used_names:
            name = f"column_{number}_{suffix}"
            suffix += 1
        columns.append(name)
        used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
